CustomCss:
/*
 * Classic TV Stick — Jellyfin Custom CSS
 * Prevue Channel inspired theme matching Kodi skin + chswitch overlays
 * VT323 retro pixel font, deep navy backgrounds, gold/cyan accents
 *
 * Install: Jellyfin Dashboard → General → Custom CSS
 */

/* Import VT323 retro font */
@import url('https://fonts.googleapis.com/css2?family=VT323&family=Share+Tech+Mono&display=swap');

/* ===== ROOT VARIABLES ===== */
:root {
  --bg-primary: #0A0A2E;
  --bg-secondary: #0D1B3E;
  --bg-card: #162450;
  --bg-dialog: #0A0F2A;
  --accent-gold: #FFD700;
  --accent-cyan: #00E5FF;
  --accent-amber: #FFB347;
  --accent-green: #00CC66;
  --accent-blue: #4169E1;
  --text-primary: #EEEEDD;
  --text-dim: #8899AA;
  --scanline: rgba(0, 0, 0, 0.04);
}

/* ===== GLOBAL ===== */
html, body {
  background: var(--bg-primary) !important;
  color: var(--text-primary) !important;
}

/* ===== SCANLINE OVERLAY (subtle CRT effect) ===== */
body::after {
  content: '';
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: repeating-linear-gradient(
    0deg,
    var(--scanline) 0px,
    var(--scanline) 1px,
    transparent 1px,
    transparent 3px
  );
  pointer-events: none;
  z-index: 9999;
  opacity: 0.3;
}

/* ===== HEADER / TOP BAR ===== */
.skinHeader {
  background: linear-gradient(180deg, #000028 0%, var(--bg-primary) 100%) !important;
  border-bottom: 2px solid var(--accent-gold) !important;
  font-family: 'VT323', monospace !important;
}

.headerTabs .emby-tab-button {
  font-family: 'VT323', monospace !important;
  font-size: 1.3em !important;
  color: var(--text-dim) !important;
  text-transform: uppercase !important;
  letter-spacing: 2px !important;
}

.headerTabs .emby-tab-button-active {
  color: var(--accent-gold) !important;
}

/* ===== SPLASH / LOGIN PAGE ===== */
.loginPage .padded-left.padded-right,
#loginPage {
  background: var(--bg-primary) !important;
}

/* Fun splash title */
.loginPage .title {
  font-family: 'VT323', monospace !important;
  font-size: 3em !important;
  color: var(--accent-gold) !important;
  text-shadow: 0 0 20px rgba(255, 215, 0, 0.5), 0 0 40px rgba(255, 215, 0, 0.2) !important;
  letter-spacing: 4px !important;
}

/* Login form styling */
.loginPage .inputContainer input {
  background: var(--bg-card) !important;
  border: 1px solid var(--accent-blue) !important;
  color: var(--text-primary) !important;
  font-family: 'Share Tech Mono', monospace !important;
  border-radius: 0 !important;
}

.loginPage .inputContainer input:focus {
  border-color: var(--accent-cyan) !important;
  box-shadow: 0 0 10px rgba(0, 229, 255, 0.3) !important;
}

.loginPage .raised.button-submit {
  background: var(--accent-gold) !important;
  color: #000028 !important;
  font-family: 'VT323', monospace !important;
  font-size: 1.4em !important;
  letter-spacing: 3px !important;
  border-radius: 0 !important;
  text-transform: uppercase !important;
}

/* ===== CARDS ===== */
.card {
  background: var(--bg-card) !important;
  border-radius: 0 !important;
  border: 1px solid rgba(65, 105, 225, 0.2) !important;
  transition: border-color 0.2s, box-shadow 0.2s !important;
}

.card:hover {
  border-color: var(--accent-cyan) !important;
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.2) !important;
}

.cardText, .cardTextCentered {
  font-family: 'Share Tech Mono', monospace !important;
  color: var(--text-primary) !important;
}

/* ===== SIDEBAR / DRAWER ===== */
.mainDrawer {
  background: var(--bg-secondary) !important;
  border-right: 2px solid var(--accent-blue) !important;
}

.navMenuOption {
  font-family: 'VT323', monospace !important;
  font-size: 1.2em !important;
  color: var(--text-dim) !important;
}

.navMenuOption:hover, .navMenuOption-selected {
  color: var(--accent-cyan) !important;
  background: rgba(0, 229, 255, 0.1) !important;
}

/* ===== DIALOGS / MODALS ===== */
.dialog, .formDialogContent, .dialogContainer {
  background: var(--bg-dialog) !important;
  border: 1px solid var(--accent-blue) !important;
  border-radius: 0 !important;
}

.formDialogHeaderTitle {
  font-family: 'VT323', monospace !important;
  color: var(--accent-gold) !important;
}

/* ===== BUTTONS ===== */
.raised, .emby-button {
  border-radius: 0 !important;
  font-family: 'Share Tech Mono', monospace !important;
  text-transform: uppercase !important;
}

.button-accent {
  background: var(--accent-blue) !important;
}

/* ===== PROGRESS BARS ===== */
.itemProgressBar {
  background: var(--bg-card) !important;
}

.itemProgressBarForeground {
  background: var(--accent-green) !important;
}

/* ===== SECTION HEADERS ===== */
.sectionTitle {
  font-family: 'VT323', monospace !important;
  color: var(--accent-amber) !important;
  font-size: 1.5em !important;
  letter-spacing: 2px !important;
  text-transform: uppercase !important;
}

/* ===== DETAIL PAGES ===== */
.detailPagePrimaryContainer .itemName {
  font-family: 'VT323', monospace !important;
  color: var(--accent-gold) !important;
}

.detailPagePrimaryContainer .itemOverview {
  font-family: 'Share Tech Mono', monospace !important;
  color: var(--text-primary) !important;
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar {
  width: 8px;
  background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
  background: var(--accent-blue);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--accent-cyan);
}

/* ===== TOAST / NOTIFICATIONS ===== */
.toast {
  background: var(--bg-card) !important;
  border-left: 3px solid var(--accent-gold) !important;
  font-family: 'Share Tech Mono', monospace !important;
  border-radius: 0 !important;
}
